"""Layer 15 MLP down-projection, component 5954: a weak, mostly word-level tendency.

What the component is: one rank-one readout of layer 15's MLP hidden units. Its activation
is noise-like around 0 (std 0.30), has no sparse firing pattern (CI is ~0 everywhere), and
switching it off barely changes the model's predictions. Its variance is mostly not
explained by the current word: a full word-identity table reaches only ~2% out of sample.

What this program does: it predicts a small signed value from the current word's class:
  +0.20  chat and code markup ('assistant', 'user', '#', '//', '@', '--', 'cd', 'git')
  +0.15  alternative and contrast openers ('or', 'either', 'if', 'but', 'however', 'also')
  -0.20  formal connective adverbs ('therefore', 'thus', 'etc', 'currently', 'respectively',
         'particularly', 'otherwise', 'which')
  +0.07  common function words and punctuation (',', 'the', 'to', 'that', 'be', 'it', ...)
  0      everything else
It uses no context: each position is judged by its own token only.
"""

READS = ()

MARKUP = {"assistant", "user", "#", "//", "///", "@", "--", "cd", "git", "bash", "/**"}
ALTERNATIVE = {"or", "either", "if", "but", "however", "also", "even"}
FORMAL_CONNECTIVE = {
    "therefore", "thus", "etc", "currently", "respectively", "particularly",
    "otherwise", "which", "generally",
}
FUNCTION_WORD = {",", "the", "to", "that", "be", "it", "by", "at", "you", ":"}


def word_value(token):
    """The predicted activation for one token, by its word class."""
    word = token.strip().lower()
    if word in MARKUP:
        return 0.20
    if word in ALTERNATIVE:
        return 0.15
    if word in FORMAL_CONNECTIVE:
        return -0.20
    if word in FUNCTION_WORD:
        return 0.07
    return 0.0


def step(carry, prefix, upstream):
    # Each position depends only on its own token, so there is no state to carry.
    return carry, word_value(prefix.token_strings[-1])

"""Word-class predictor for component 5962 of layers.15.mlp.down_proj (rank-1 piece of the MLP output).

What it does: it looks only at the newest token and guesses the component's activation
from a few word classes, using the average activation seen for each class on training text:
  - reflexive words ("own", "themselves", "himself", "self", ...) -> negative on average
    ("itself" averages positive, so this class is only a rough guess),
  - "same", "very", "by" and similar -> positive,
  - the word "the" -> slightly positive,
  - digits and punctuation / code symbols -> slightly negative,
  - every other token -> the overall mean (about -0.04).

Why: when positive, the component writes along a direction that promotes reflexive words
("itself", "themselves", "own", "self") in the next-token distribution, and its gate opens
most often on "the", "own", "itself", "same". The class means explain only a little of its
variance (about 0.4% on eval): the activation is dense, heavy-tailed and mostly depends on
context that no word class captures.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

REFLEXIVE = {"own", "itself", "themselves", "himself", "herself", "myself", "yourself",
             "ourselves", "oneself", "self", "selves", "yourselves"}
SAME_LIKE = {"same", "very", "by", "mismo", "même"}
DIGITS = set("0123456789")
MEAN = -0.04
VALUES = {"reflexive": -0.19, "same_like": 0.18, "the": 0.06, "digit": -0.08, "symbol": -0.05}


def word_class(token: str) -> str:
    word = token.strip().lower()
    if word in REFLEXIVE:
        return "reflexive"
    if word in SAME_LIKE:
        return "same_like"
    if word == "the":
        return "the"
    if word and all(ch in DIGITS for ch in word):
        return "digit"
    if word and not any(ch.isalnum() for ch in word):
        return "symbol"
    return "other"


def step(carry, prefix, upstream: Mapping):
    cls = word_class(prefix.token_strings[-1])
    return carry, VALUES.get(cls, MEAN)

"""Person-and-group nouns pull this component negative.

Component p-82af68dd@100000/layers.15.mlp.down_proj:5964 is one rank-one piece of the MLP
down projection in layer 15. Its activation is mostly diffuse, but its strongest, most
reliable behaviour is on nouns for people and social groups ("people", "person", "team",
"women", "company", "students", "government") and on the chat role words "user" and
"assistant". Those tokens drive it clearly negative; the strongest cases are role words
and people-nouns right after a determiner or possessive ("the people", "his team",
"<|im_start|>user"). Other concrete nouns (animals, food, plants, objects, places,
body parts) are mildly negative. Everything else is predicted as 0.

The predicted values are scaled to the activation's size, since the component's
activation is typically a fraction of a unit on most tokens.
"""

import wordnet

ROLE_WORDS = {"user", "assistant", "speaker"}
DETERMINERS = {
    "the", "a", "an", "his", "her", "their", "our", "your", "my", "its",
    "other", "many", "some", "all", "these", "those", "few", "two", "three",
    "of", "and", "for", "with", "by", "from",
}
PEOPLE_CATEGORIES = {"noun.person", "noun.group"}
CONCRETE_CATEGORIES = {
    "noun.animal", "noun.food", "noun.plant", "noun.artifact", "noun.object",
    "noun.body", "noun.shape", "noun.substance", "noun.location", "noun.Tops",
}

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()
    if word in ROLE_WORDS:
        return carry, -2.3
    if not (word.isalpha() and word.isascii()):
        return carry, 0.0
    categories = wordnet.categories(word)
    if categories & PEOPLE_CATEGORIES:
        return carry, (-0.9 if previous in DETERMINERS else -0.4)
    if categories & CONCRETE_CATEGORIES:
        return carry, -0.1
    return carry, 0.0
